import{_ as o,c as r,ag as e,o as s}from"./chunks/framework.-a8jReyC.js";const m=JSON.parse('{"title":"Começando com FlyCash","description":"","frontmatter":{"title":"Começando com FlyCash"},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),t={name:"getting-started.md"};function i(n,a,l,c,p,u){return s(),r("div",null,a[0]||(a[0]=[e('<h1 id="comecando-com-flycash-🚀" tabindex="-1">Começando com FlyCash 🚀 <a class="header-anchor" href="#comecando-com-flycash-🚀" aria-label="Permalink to &quot;Começando com FlyCash 🚀&quot;">​</a></h1><p>Bem-vindo ao FlyCash, sua ferramenta para gerenciar finanças de forma simples e eficiente! Aqui você encontra tudo o que precisa para começar a organizar suas finanças pessoais e aproveitar ao máximo os recursos do aplicativo.</p><h2 id="o-que-e-o-flycash-💡" tabindex="-1">O que é o FlyCash? 💡 <a class="header-anchor" href="#o-que-e-o-flycash-💡" aria-label="Permalink to &quot;O que é o FlyCash? 💡&quot;">​</a></h2><p>O FlyCash é um <strong>gerenciador financeiro intuitivo</strong> que ajuda você a:</p><ul><li><strong>Registrar gastos do dia a dia</strong> de forma rápida — do cafezinho à conta de luz.</li><li><strong>Importar a fatura do cartão</strong> (PDF ou OFX) e ver as compras entrarem já categorizadas.</li><li><strong>Acompanhar transações</strong> em tempo real.</li><li><strong>Configurar recorrências</strong> para pagamentos e receitas automáticos.</li><li><strong>Analisar seu fluxo de caixa</strong> com gráficos e relatórios por categoria.</li></ul><p>Seja para controle diário ou planejamento de longo prazo, o FlyCash está aqui para simplificar sua vida financeira.</p><h2 id="como-criar-uma-conta-📝" tabindex="-1">Como criar uma conta? 📝 <a class="header-anchor" href="#como-criar-uma-conta-📝" aria-label="Permalink to &quot;Como criar uma conta? 📝&quot;">​</a></h2><p>Criar uma conta no FlyCash é rápido e fácil. Siga os passos abaixo:</p><ol><li><p><strong>Acesse o site:</strong><br> Vá para <a href="https://flyca.sh" target="_blank" rel="noreferrer">https://flyca.sh</a>.</p></li><li><p><strong>Clique em &quot;Comece Grátis&quot;:</strong><br> Encontre o botão no topo da página.</p></li><li><p><strong>Autentique com sua conta Google:</strong><br> A forma de se registrar no FlyCash é utilizando sua conta do Google. Basta clicar no botão &quot;Continuar com Google&quot; e seguir as instruções.</p></li><li><p><strong>Pronto!</strong><br> Agora você pode acessar sua conta e começar a usar o FlyCash.</p></li></ol><h2 id="primeiros-passos-no-flycash-🛠️" tabindex="-1">Primeiros Passos no FlyCash 🛠️ <a class="header-anchor" href="#primeiros-passos-no-flycash-🛠️" aria-label="Permalink to &quot;Primeiros Passos no FlyCash 🛠️&quot;">​</a></h2><p>Depois de criar sua conta, siga estas dicas para começar:</p><ol><li><p><strong>Crie seus primeiros grupos:</strong><br> Exemplo: <strong>Despesas</strong>, <strong>Receitas</strong>, <strong>Investimentos</strong>.</p></li><li><p><strong>Adicione categorias e subcategorias:</strong><br> Dentro de <strong>Despesas</strong>, crie categorias como <strong>Casa</strong>, <strong>Transporte</strong> e <strong>Lazer</strong>.</p></li><li><p><strong>Registre suas primeiras transações:</strong><br> Adicione entradas e saídas manualmente — ou importe a fatura do cartão para agilizar.</p></li><li><p><strong>Explore as funcionalidades:</strong><br> Configure transações recorrentes, crie saldos personalizados e acompanhe o fluxo de caixa.</p></li></ol><h2 id="duas-formas-de-registrar-seus-gastos-✍️" tabindex="-1">Duas formas de registrar seus gastos ✍️ <a class="header-anchor" href="#duas-formas-de-registrar-seus-gastos-✍️" aria-label="Permalink to &quot;Duas formas de registrar seus gastos ✍️&quot;">​</a></h2><h3 id="_1-registro-manual-na-hora" tabindex="-1">1. Registro manual (na hora) <a class="header-anchor" href="#_1-registro-manual-na-hora" aria-label="Permalink to &quot;1. Registro manual (na hora)&quot;">​</a></h3><p>Pagou o lanche, a passagem ou o mercado? Anote em segundos, direto do celular ou computador:</p><ol><li>Selecione o mês de referência em uma categoria.</li><li>Clique em <strong><code>Adicionar Transação</code></strong>.</li><li>Preencha <strong><code>Data</code></strong>, <strong><code>Valor</code></strong> e opcionalmente <strong><code>Descrição</code></strong>.</li><li>Clique em <strong><code>Salvar</code></strong>.</li></ol><h3 id="_2-importacao-de-fatura-tudo-de-uma-vez" tabindex="-1">2. Importação de fatura (tudo de uma vez) <a class="header-anchor" href="#_2-importacao-de-fatura-tudo-de-uma-vez" aria-label="Permalink to &quot;2. Importação de fatura (tudo de uma vez)&quot;">​</a></h3><p>Quer agilizar? Baixe o arquivo da fatura do cartão (PDF ou OFX) no app do seu banco e anexe no FlyCash:</p><ol><li>Abra a janela de <strong>importação</strong> (no módulo de transações).</li><li>Anexe o arquivo <code>fatura.pdf</code> ou <code>fatura.ofx</code>.</li><li>Revise as transações que entraram, já com categorias sugeridas.</li><li>Confirme e pronto — sem digitar linha por linha.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>O FlyCash aponta <strong>possíveis duplicatas</strong> na importação, para você não registrar duas vezes a mesma compra.</p></div><p><a href="/features/import-transactions.html">Veja o guia completo de importação</a></p><h2 id="planos-e-precos-💳" tabindex="-1">Planos e Preços 💳 <a class="header-anchor" href="#planos-e-precos-💳" aria-label="Permalink to &quot;Planos e Preços 💳&quot;">​</a></h2><p>O FlyCash oferece três planos para atender às suas necessidades:</p><h3 id="controle-inicial-gratis" tabindex="-1"><strong>Controle Inicial (Grátis)</strong> <a class="header-anchor" href="#controle-inicial-gratis" aria-label="Permalink to &quot;**Controle Inicial (Grátis)**&quot;">​</a></h3><ul><li>Até <strong>10 categorias</strong>, <strong>3 saldos</strong> e <strong>100 transações por mês</strong>.</li><li><strong>1 importação de fatura por mês</strong>.</li><li><strong>Ideal para:</strong> quem quer experimentar a ferramenta sem compromisso.</li></ul><h3 id="essencial-r-6-90-mes" tabindex="-1"><strong>Essencial (R$ 6,90/mês)</strong> <a class="header-anchor" href="#essencial-r-6-90-mes" aria-label="Permalink to &quot;**Essencial (R$ 6,90/mês)**&quot;">​</a></h3><ul><li><strong>Categorias, saldos e transações ilimitados.</strong></li><li><strong>Importação de faturas ilimitada.</strong></li><li><strong>Análise por categoria</strong> (totais e principais transações).</li><li><strong>Ideal para:</strong> quem quer organizar as finanças sem limites.</li></ul><h3 id="equilibrio-total-r-14-90-mes" tabindex="-1"><strong>Equilíbrio Total (R$ 14,90/mês)</strong> <a class="header-anchor" href="#equilibrio-total-r-14-90-mes" aria-label="Permalink to &quot;**Equilíbrio Total (R$ 14,90/mês)**&quot;">​</a></h3><ul><li>Tudo do Essencial, <strong>sem limites</strong>.</li><li><strong>Relatórios avançados</strong> (análise por categoria com comparativo e variação).</li><li><strong>Exportação XLSX</strong> e <strong>suporte prioritário</strong>.</li><li><strong>Ideal para:</strong> quem busca controle financeiro total.</li></ul><p><a href="/plans-and-pricing.html">Compare os planos em detalhes</a></p><h2 id="funcionalidades-principais-✨" tabindex="-1">Funcionalidades Principais ✨ <a class="header-anchor" href="#funcionalidades-principais-✨" aria-label="Permalink to &quot;Funcionalidades Principais ✨&quot;">​</a></h2><ul><li><p><strong>📂 Organização por Grupos e Categorias:</strong><br> Classifique suas transações de forma clara e intuitiva.</p></li><li><p><strong>🔁 Transações Recorrentes:</strong><br> Automatize pagamentos e receitas com recorrências personalizáveis.</p></li><li><p><strong>📥 Importação de Faturas:</strong><br> Importe PDF/OFX e ganhe tempo com a categorização automática.</p></li><li><p><strong>📊 Fluxo de Caixa:</strong><br> Acompanhe sua saúde financeira com gráficos e relatórios.</p></li><li><p><strong>📊 Visualização de Saldos:</strong><br> Crie saldos personalizados para acompanhar suas metas financeiras.</p></li></ul><p><a href="/features/">Explore todas as funcionalidades em detalhes</a></p><h2 id="dicas-para-comecar-🚀" tabindex="-1">Dicas para Começar 🚀 <a class="header-anchor" href="#dicas-para-comecar-🚀" aria-label="Permalink to &quot;Dicas para Começar 🚀&quot;">​</a></h2><ul><li><p><strong>Importe sua primeira fatura:</strong><br> Se você usa cartão de crédito, comece importando a fatura — a categorização automática faz o trabalho pesado.</p></li><li><p><strong>Crie transações recorrentes:</strong><br> Automatize contas fixas como aluguel, luz e internet.</p></li><li><p><strong>Anote pequenos gastos na hora:</strong><br> O cafezinho e a passagem somam no fim do mês. Registrar na hora evita esquecimento.</p></li><li><p><strong>Explore os saldos personalizados:</strong><br> Crie cálculos específicos para entender melhor suas finanças.</p></li></ul><h2 id="precisa-de-ajuda-🤔" tabindex="-1">Precisa de Ajuda? 🤔 <a class="header-anchor" href="#precisa-de-ajuda-🤔" aria-label="Permalink to &quot;Precisa de Ajuda? 🤔&quot;">​</a></h2><ul><li><strong>FAQ:</strong> Consulte as perguntas frequentes para respostas rápidas.</li><li><strong>Suporte:</strong> Envie um email para <a href="mailto:support@flyca.sh" target="_blank" rel="noreferrer">support@flyca.sh</a> ou acesse a <a href="https://flyca.sh/support" target="_blank" rel="noreferrer">página de suporte</a>.</li></ul><h2 id="pronto-para-comecar-💸" tabindex="-1">Pronto para Começar? 💸 <a class="header-anchor" href="#pronto-para-comecar-💸" aria-label="Permalink to &quot;Pronto para Começar? 💸&quot;">​</a></h2><p>Agora que você já sabe como começar, é hora de colocar suas finanças em ordem com o FlyCash!</p><p><a href="https://flyca.sh" target="_blank" rel="noreferrer">Experimente Grátis 💸</a></p>',40)]))}const g=o(t,[["render",i]]);export{m as __pageData,g as default};
